import { z } from 'zod';

export const AddLoanTypeSchema = z.object({
    loan_type: z.string().min(1, 'Loan type field is required.'),
    max_amount: z.string().min(1, 'Max amount field is required.'),
    return_amount: z.string().min(1, 'Return amount field is required.'),
    duration_in_months: z.string().min(1, 'Duration field is required.'),
});

export type AddLoanTypeFormValues = z.infer<typeof AddLoanTypeSchema>;
