import { loanTypes } from '@/features/selfServices/types/loanTypes.types';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import AddIcon from '@/components/icons/AddIcon';
import { useState } from 'react';
import LoanTypePopup from '../../LoanTypePopup';

export default function LoanTypesStatistics() {
    const [showPopup, setShowPopup] = useState(false);

    return (
        <>
            <div className="flex items-center justify-end w-full mt-6">
                <PrimaryButton
                    onClick={() => setShowPopup(true)}
                    className="text-base px-[14px] xl:py-2 leading-5 font-semibold font-cairo tracking-normal"
                >
                    <AddIcon />
                    <p className="text-xs tracking-normal font-normal leading-[22.49px]">انشاء قرض</p>
                </PrimaryButton>
            </div>
            <div className="flex flex-wrap gap-6 w-full mt-4">
                {loanTypes.map((loan, idx) => (
                    <div
                        key={idx}
                        className="flex-1 rounded-2xl border border-[#B6CDE2] bg-[#F4F8FB] p-6 flex items-center justify-between gap-2 shadow-sm min-w-[260px]"
                    >
                        <div className="text-sm text-gray-700 text-start font-extrabold">
                            <div className="font-bold text-xl text-start mt-2 mb-1">{loan.title}</div>
                            <div>
                                <span className="font-bold">{loan.maxLabel}</span> {loan.amount}
                            </div>
                            <div>
                                <span className="font-bold">{loan.durationLabel}</span> {loan.duration}
                            </div>
                            <div>
                                <span className="font-bold">{loan.rateLabel}</span> {loan.rate}
                            </div>
                        </div>
                        {loan.icon}
                    </div>
                ))}
            </div>
            <LoanTypePopup open={showPopup} setShowPopup={setShowPopup} handleRefreshTable={() => undefined} />
        </>
    );
}
